1|/*
2| * json_pack_unpack_fuzzer.cc
3| *
4| * Fuzz harness for jansson json_unpack() and json_deep_copy() paths.
5| * json_unpack() processes a format string + JSON value and extracts
6| * typed fields — it involves non-trivial string/type dispatch that
7| * is not exercised by the load/dump fuzzer.
8| *
9| * OSS-Fuzz build: compiled via test/ossfuzz/ossfuzz.sh.
10| */
