642|static int lex_init(lex_t *lex, get_func get, size_t flags, void *data) {
643|    stream_init(&lex->stream, get, data);
644|    if (strbuffer_init(&lex->saved_text))
645|        return -1;
646|
647|    lex->flags = flags;
648|    lex->token = TOKEN_INVALID;
