850|static json_t *parse_json(lex_t *lex, size_t flags, json_error_t *error) {
851|    json_t *result;
852|
853|    lex->depth = 0;
854|
855|    lex_scan(lex, error);
856|    if (!(flags & JSON_DECODE_ANY)) {
857|        if (lex->token != '[' && lex->token != '{') {
858|            error_set(error, lex, json_error_invalid_syntax, "'[' or '{' expected");
859|            return NULL;
860|        }
861|    }
862|
863|    result = parse_value(lex, flags, error);
864|    if (!result)
865|        return NULL;
866|
867|    if (!(flags & JSON_DISABLE_EOF_CHECK)) {
868|        lex_scan(lex, error);
869|        if (lex->token != TOKEN_EOF) {
870|            error_set(error, lex, json_error_end_of_input_expected,
871|                      "end of file expected");
872|            json_decref(result);
873|            return NULL;
874|        }
875|    }
876|
877|    if (error) {
878|        /* Save the position even though there was no error */
879|        error->position = (int)lex->stream.position;
880|    }
881|
882|    return result;
883|}

652|static void lex_close(lex_t *lex) {
653|    if (lex->token == TOKEN_STRING)
654|        lex_free_string(lex);
655|    strbuffer_close(&lex->saved_text);
656|}

431|static json_t *pack(scanner_t *s, va_list *ap) {
432|    switch (token(s)) {
433|        case '{':
434|            return pack_object(s, ap);
435|
436|        case '[':
437|            return pack_array(s, ap);
438|
439|        case 's': /* string */
440|            return pack_string(s, ap);
441|
442|        case 'n': /* null */
443|            return json_null();
444|
445|        case 'b': /* boolean */
446|            return va_arg(*ap, int) ? json_true() : json_false();
447|
448|        case 'i': /* integer from int */
449|            return pack_integer(s, va_arg(*ap, int));
450|
451|        case 'I': /* integer from json_int_t */
452|            return pack_integer(s, va_arg(*ap, json_int_t));
453|
454|        case 'f': /* real */
455|            return pack_real(s, va_arg(*ap, double));
456|
457|        case 'O': /* a json_t object; increments refcount */
458|            return pack_object_inter(s, ap, 1);
459|
460|        case 'o': /* a json_t object; doesn't increment refcount */
461|            return pack_object_inter(s, ap, 0);
462|
463|        default:
464|            set_error(s, "<format>", json_error_invalid_format,
465|                      "Unexpected format character '%c'", token(s));
466|            s->has_error = 1;
467|            return NULL;
468|    }
469|}

473|static int unpack_object(scanner_t *s, json_t *root, va_list *ap,
474|                         const char *parent_key) {
475|    int ret = -1;
476|    int strict = 0;
477|    int gotopt = 0;
478|
479|    /* Use a set (emulated by a hashtable) to check that all object
480|       keys are accessed. Checking that the correct number of keys
481|       were accessed is not enough, as the same key can be unpacked
482|       multiple times.
483|    */
484|    hashtable_t key_set;
485|
486|    if (hashtable_init(&key_set)) {
487|        set_error(s, "<internal>", json_error_out_of_memory, "Out of memory");
488|        return -1;
489|    }
490|
491|    if (root && !json_is_object(root)) {
492|        set_error(s, "<validation>", json_error_wrong_type, "Expected object, got %s%s%s",
493|                  type_name(root), parent_key ? " for key " : "",
494|                  parent_key ? parent_key : "");
495|        goto out;
496|    }
497|    next_token(s);
498|
499|    while (token(s) != '}') {
500|        const char *key;
501|        size_t key_len;
502|        json_t *value;
503|        int opt = 0;
504|
505|        if (strict != 0) {
506|            set_error(s, "<format>", json_error_invalid_format,
507|                      "Expected '}' after '%c', got '%c'", (strict == 1 ? '!' : '*'),
508|                      token(s));
509|            goto out;
510|        }
511|
512|        if (!token(s)) {
513|            set_error(s, "<format>", json_error_invalid_format,
514|                      "Unexpected end of format string");
515|            goto out;
516|        }
517|
518|        if (token(s) == '!' || token(s) == '*') {
519|            strict = (token(s) == '!' ? 1 : -1);
520|            next_token(s);
521|            continue;
522|        }
523|
524|        if (token(s) != 's') {
525|            set_error(s, "<format>", json_error_invalid_format,
526|                      "Expected format 's', got '%c'", token(s));
527|            goto out;
528|        }
529|
530|        key = va_arg(*ap, const char *);
531|        if (!key) {
532|            set_error(s, "<args>", json_error_null_value, "NULL object key");
533|            goto out;
534|        }
535|        key_len = strlen(key);
536|
537|        next_token(s);
538|
539|        if (token(s) == '?') {
540|            opt = gotopt = 1;
541|            next_token(s);
542|        }
543|
544|        if (!root) {
545|            /* skipping */
546|            value = NULL;
547|        } else {
548|            value = json_object_getn(root, key, key_len);
549|            if (!value && !opt) {
550|                set_error(s, "<validation>", json_error_item_not_found,
551|                          "Object item not found: %s", key);
552|                goto out;
553|            }
554|        }
555|
556|        if (unpack(s, value, ap, key))
557|            goto out;
558|
559|        hashtable_set(&key_set, key, key_len, json_null());
560|        next_token(s);
561|    }
562|
563|    if (strict == 0 && (s->flags & JSON_STRICT))
564|        strict = 1;
565|
566|    if (root && strict == 1) {
567|        /* We need to check that all non optional items have been parsed */
568|        const char *key;
569|        size_t key_len;
570|        /* keys_res is 1 for uninitialized, 0 for success, -1 for error. */
571|        int keys_res = 1;
572|        strbuffer_t unrecognized_keys;
573|        json_t *value;
574|        long unpacked = 0;
575|
576|        if (gotopt || json_object_size(root) != key_set.size) {
577|            json_object_keylen_foreach(root, key, key_len, value) {
578|                if (!hashtable_get(&key_set, key, key_len)) {
579|                    unpacked++;
580|
581|                    /* Save unrecognized keys for the error message */
582|                    if (keys_res == 1) {
583|                        keys_res = strbuffer_init(&unrecognized_keys);
584|                    } else if (!keys_res) {
585|                        keys_res = strbuffer_append_bytes(&unrecognized_keys, ", ", 2);
586|                    }
587|
588|                    if (!keys_res)
589|                        keys_res =
590|                            strbuffer_append_bytes(&unrecognized_keys, key, key_len);
591|                }
592|            }
593|        }
594|        if (unpacked) {
595|            set_error(s, "<validation>", json_error_end_of_input_expected,
596|                      "%li object item(s) left unpacked: %s", unpacked,
597|                      keys_res ? "<unknown>" : strbuffer_value(&unrecognized_keys));
598|            strbuffer_close(&unrecognized_keys);
599|            goto out;
600|        }
601|    }
602|
603|    ret = 0;
604|
605|out:
606|    hashtable_close(&key_set);
607|    return ret;
608|}

610|static int unpack_array(scanner_t *s, json_t *root, va_list *ap, const char *parent_key) {
611|    size_t i = 0;
